# Environment for the Wayland session. Sourced by /etc/profile at login.

# Where the compositor creates its socket (wayland-0) and clients look for it.
export XDG_RUNTIME_DIR=/run/user/$(id -u)
mkdir -p "$XDG_RUNTIME_DIR"
chmod 0700 "$XDG_RUNTIME_DIR"

# The UTF-8 locale generated by BR2_GENERATE_LOCALE in perkinsos_defconfig.
export LANG=en_US.UTF-8

# Draw with wlroots' software (pixman) renderer. It works on plain
# virtio-gpu with no 3D acceleration on the host, so it behaves the same
# on WSL2 and in CI. Unset this to try the GLES2 renderer with virgl.
export WLR_RENDERER=pixman

# Draw the cursor into the frame instead of using the GPU's cursor plane,
# so it also appears in QEMU screenshots (used by the CI test).
export WLR_NO_HARDWARE_CURSORS=1
